<script setup lang="ts">
import {ref} from 'vue'
import {Plus,Trash2,Save} from 'lucide-vue-next'
import {api,notify,type Row} from '../lib'
const props=defineProps<{value:Row}>(),emit=defineEmits<{saved:[]}>()
const tiers=ref<Row[]>((props.value.items||[]).map((t:Row,i:number)=>({...t,code:t.code||'L'+(i+1),threshold_R:t.threshold/100}))),busy=ref(false),error=ref('')
function add(){let n=tiers.value.length+1;while(tiers.value.some(t=>t.code==='L'+n))n++;tiers.value.push({code:'L'+n,name:'',threshold_R:Number(tiers.value.at(-1)?.threshold_R||0)+1000,discount:tiers.value.at(-1)?.discount||100,description:''})}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const items=tiers.value.map(t=>({code:t.code.trim(),name:t.name.trim(),threshold:Math.round(Number(t.threshold_R)*100),discount:Number(t.discount),description:t.description||''})).sort((a,b)=>a.threshold-b.threshold);await api('/admin/settings/tiers','PUT',{items});notify('会员等级规则已保存');emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><form class="tier-editor" @submit.prevent="save"><div class="callout">按成功订单实际结算服务费累计，扣除已退服务费；充值、兑换和人工调账不计入。第一档门槛必须为 0，后续门槛递增，优惠不能变差。保存后影响新报价，历史订单保留原价。</div><div v-if="error" class="alert danger">{{error}}</div><article v-for="(t,i) in tiers" :key="i" class="tier-editor-row"><div class="section-heading"><h3>等级 {{i+1}}</h3><button type="button" class="text-btn danger-text" :disabled="tiers.length===1" @click="tiers.splice(i,1)" :aria-label="'删除等级 '+(i+1)"><Trash2 :size="16"/>移除</button></div><div class="form-grid"><label>等级标识<input v-model="t.code" required pattern="[A-Z][A-Z0-9_]{0,15}" maxlength="16" placeholder="L1"/></label><label>会员名称<input v-model="t.name" required maxlength="26"/></label><label>累计消费门槛（R）<input v-model.number="t.threshold_R" type="number" min="0" max="100000000" step="0.01" required/></label><label>服务费实付比例（%）<input v-model.number="t.discount" type="number" min="1" max="100" step="1" required/><small>填 95 即减免 5%；填 20 即减免 80%</small></label><label class="span2">等级说明<input v-model="t.description" maxlength="160"/></label></div></article><div class="form-footer"><button type="button" class="btn secondary" :disabled="tiers.length>=10" @click="add"><Plus :size="16"/>新增等级</button><button class="btn primary" :disabled="busy"><Save :size="16"/>保存等级规则</button></div></form></template>
